//! The Metal implementation of [`crate::sched::Backend`], for kernels generated by the Tree compiler
//! (`Code::Msl`, see `stdlib/tree_msl.ss`).
//!
//! Calling convention (`OffsetMode::Prefix`, as on Vulkan):
//!
//! * buffer `i` of the signature is `[[buffer(i)]]`, bound at its byte offset rounded down to
//!   [`OFFSET_ALIGN`];
//! * when there are bindings or push bytes, ONE `constant uint*` at `[[buffer(n)]]` (n = number of
//!   bindings) holds the residual byte offset of every binding, then the kernel's push words;
//! * the launch grid is the number of threadgroups and `sig.workgroup` the threadgroup shape.
//!
//! Buffers are shared storage (unified memory), so host copies are plain `memcpy`s; the engine only
//! touches memory the GPU is not using (fresh or returned arenas, weights before the first run).
//! A submission is one command buffer with one concurrent compute encoder; the barrier groups of the
//! hazard analysis become `memoryBarrierWithScope(buffers)` between groups, and launches of one
//! group may overlap.

use std::ptr::NonNull;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use objc2::rc::Retained;
use objc2::runtime::ProtocolObject;
use objc2_metal::{
    MTLBarrierScope, MTLCommandBuffer, MTLCommandBufferStatus, MTLCommandEncoder, MTLCommandQueue, MTLComputeCommandEncoder,
    MTLDispatchType, MTLSize,
};

use super::{Buffer, Device, Kernel};
use crate::sched::backend::{Backend, Launch, Limits, MemKind};
use crate::sched::blob::{Code, KernelBlob, Target};
use crate::{Error, Result};

/// Buffers up to this size are copied into launch records (`TL_METAL_LAUNCHES`).
const SNAPSHOT_BYTES: u64 = 4096;

/// Alignment of a binding's start; the rest is the residual passed in the push words.
pub const OFFSET_ALIGN: u64 = 16;

/// Per-kernel GPU time (`TL_METAL_PROFILE=1`): every launch gets its own command buffer, so a run is
/// slower; the table (label, launches, total ms) is printed when the last handle to the backend goes.
#[derive(Default)]
struct Profile {
    on: bool,
    kernels: Mutex<HashMap<String, (u64, f64)>>,
    /// `TL_METAL_LAUNCHES=<file>`: every distinct launch (kernel label, grid, push bytes, binding lengths) with
    /// its count and the contents of its small buffers (index and position buffers: random data there would read out of
    /// bounds; taken when the launch is encoded, so one a previous kernel writes shows the previous value), appended as JSON lines when the last handle goes. `tl-evolve` replays these to benchmark kernels.
    launches_path: Option<std::path::PathBuf>,
    launches: Mutex<HashMap<(String, [u32; 3], Vec<u8>, Vec<u64>), (u64, Vec<Option<Vec<u8>>>)>>,
}

impl Drop for Profile {
    fn drop(&mut self) {
        if let Some(path) = &self.launches_path {
            let launches = self.launches.lock().unwrap();
            if !launches.is_empty() {
                let mut rows: Vec<_> = launches.iter().collect();
                rows.sort();
                let mut out = String::new();
                for ((label, grid, push, bind), (n, data)) in rows {
                    let hex = |v: &[u8]| -> String { v.iter().map(|b| format!("{b:02x}")).collect() };
                    let data: Vec<String> = data.iter().map(|d| d.as_ref().map(|d| format!("\"{}\"", hex(d))).unwrap_or_else(|| "null".into())).collect();
                    out.push_str(&format!("{{\"label\":{label:?},\"grid\":{grid:?},\"push\":\"{}\",\"bind\":{bind:?},\"data\":[{}],\"count\":{n}}}\n", hex(push), data.join(",")));
                }
                // every Metal handle (one per test, say) appends its own table; readers add up equal rows
                use std::io::Write;
                let written = std::fs::OpenOptions::new().create(true).append(true).open(path).and_then(|mut f| f.write_all(out.as_bytes()));
                if let Err(e) = written {
                    eprintln!("metal: cannot write {}: {e}", path.display());
                }
            }
        }
        let kernels = self.kernels.lock().unwrap();
        if !self.on || kernels.is_empty() {
            return;
        }
        let mut rows: Vec<_> = kernels.iter().collect();
        rows.sort_by(|a, b| b.1 .1.total_cmp(&a.1 .1));
        let total: f64 = rows.iter().map(|r| r.1 .1).sum();
        eprintln!("metal profile: {total:.2} ms over {} kernels", rows.len());
        for (label, (n, ms)) in rows.iter().take(30) {
            eprintln!("  {ms:9.3} ms {n:6} x {:8.1} us  {label}", ms * 1e3 / *n as f64);
        }
    }
}

#[derive(Clone)]
pub struct Metal {
    dev: Arc<Device>,
    profile: Arc<Profile>,
}

impl Metal {
    pub fn system_default() -> Result<Metal> {
        Ok(Metal::from_device(Arc::new(Device::system_default()?)))
    }

    /// Wraps an existing device.
    pub fn from_device(dev: Arc<Device>) -> Metal {
        let on = std::env::var_os("TL_METAL_PROFILE").is_some_and(|v| v != "0");
        let launches_path = std::env::var_os("TL_METAL_LAUNCHES").filter(|v| !v.is_empty()).map(std::path::PathBuf::from);
        Metal { dev, profile: Arc::new(Profile { on, kernels: Mutex::new(HashMap::new()), launches_path, launches: Mutex::new(HashMap::new()) }) }
    }

    pub fn device(&self) -> &Arc<Device> {
        &self.dev
    }

    /// Seconds the GPU spent on a submission (start to end of its command buffer); waits for it.
    pub fn gpu_seconds(&self, pending: &Pending) -> f64 {
        pending.cmd.waitUntilCompleted();
        pending.cmd.GPUEndTime() - pending.cmd.GPUStartTime()
    }
}

pub struct Pipeline {
    label: String,
    pipeline: super::Pipeline,
    threads: [u32; 3],
    bindings: usize,
    push_bytes: usize,
}

/// A committed command buffer; dropping it waits for the work.
pub struct Pending {
    cmd: Retained<ProtocolObject<dyn MTLCommandBuffer>>,
}

// SAFETY: MTLCommandBuffer is thread-safe once committed.
unsafe impl Send for Pending {}

impl Drop for Pending {
    fn drop(&mut self) {
        self.cmd.waitUntilCompleted();
    }
}

fn check(cmd: &ProtocolObject<dyn MTLCommandBuffer>) -> Result<()> {
    if cmd.status() == MTLCommandBufferStatus::Error {
        let msg = cmd.error().map(|e| e.localizedDescription().to_string()).unwrap_or_default();
        return Err(Error::Execution(msg));
    }
    Ok(())
}

impl Backend for Metal {
    type Buffer = Buffer;
    type Pipeline = Pipeline;
    type Pending = Pending;

    const TARGET: Target = Target::Metal;

    fn name(&self) -> String {
        format!("metal {}", self.dev.name())
    }

    fn limits(&self) -> Limits {
        Limits {
            max_buffer_bytes: self.dev.max_buffer_len() as u64,
            storage_offset_align: OFFSET_ALIGN,
            // [[buffer(0..30)]]: the residual/push words take one slot.
            max_bindings: 30,
            max_push_bytes: 4096,
            max_workgroup_invocations: 1024,
            max_groups: [i32::MAX as u32, 65535, 65535],
        }
    }

    fn alloc(&self, bytes: u64, _kind: MemKind) -> Result<Buffer> {
        self.dev.alloc(bytes as usize)
    }

    fn buffer_len(&self, buf: &Buffer) -> u64 {
        buf.len() as u64
    }

    fn write(&self, buf: &Buffer, off: u64, data: &[u8]) -> Result<()> {
        if off + data.len() as u64 > buf.len() as u64 {
            return Err(Error::Invalid(format!("write of {} bytes at {off} is past a buffer of {}", data.len(), buf.len())));
        }
        unsafe { std::ptr::copy_nonoverlapping(data.as_ptr(), buf.contents().add(off as usize), data.len()) };
        Ok(())
    }

    fn read(&self, buf: &Buffer, off: u64, out: &mut [u8]) -> Result<()> {
        if off + out.len() as u64 > buf.len() as u64 {
            return Err(Error::Invalid(format!("read of {} bytes at {off} is past a buffer of {}", out.len(), buf.len())));
        }
        unsafe { std::ptr::copy_nonoverlapping(buf.contents().add(off as usize), out.as_mut_ptr(), out.len()) };
        Ok(())
    }

    fn zero(&self, buf: &Buffer, off: u64, len: u64) -> Result<()> {
        if off + len > buf.len() as u64 {
            return Err(Error::Invalid(format!("zero of {len} bytes at {off} is past a buffer of {}", buf.len())));
        }
        unsafe { std::ptr::write_bytes(buf.contents().add(off as usize), 0, len as usize) };
        Ok(())
    }

    fn pipeline(&self, blob: &KernelBlob) -> Result<Pipeline> {
        let Code::Msl(source) = &blob.code else {
            return Err(Error::Invalid(format!("the Metal backend takes MSL blobs, `{}` is {:?}", blob.entry, blob.target)));
        };
        if blob.sig.bindings.len() > 30 {
            return Err(Error::Invalid(format!("`{}` has too many bindings", blob.entry)));
        }
        let key = format!("blob-{:016x}", blob.id());
        // No fast math: exp/tanh/... must keep their IEEE behaviour (masked scores are -inf).
        let library = self.dev.library_precise(&key, || source.clone())?;
        let pipeline = self.dev.pipeline(&Kernel { library, entry: blob.entry.clone(), consts: vec![] })?;
        let threads: usize = blob.sig.workgroup.iter().map(|&n| n as usize).product();
        if threads > pipeline.max_threads {
            return Err(Error::Pipeline {
                entry: blob.label.clone(),
                msg: format!("a threadgroup of {threads} threads is over the pipeline's limit of {}", pipeline.max_threads),
            });
        }
        Ok(Pipeline { label: blob.label.clone(), pipeline, threads: blob.sig.workgroup, bindings: blob.sig.bindings.len(), push_bytes: blob.sig.push_bytes as usize })
    }

    fn submit(&self, groups: &[Vec<Launch<'_, Self>>]) -> Result<Pending> {
        if self.profile.on {
            let mut last = None;
            for l in groups.iter().flatten() {
                let pending = self.submit_one(&[], Some(l))?;
                pending.cmd.waitUntilCompleted();
                let ms = (pending.cmd.GPUEndTime() - pending.cmd.GPUStartTime()) * 1e3;
                let mut k = self.profile.kernels.lock().unwrap();
                let e = k.entry(format!("{} grid={:?}", l.pipeline.label, l.grid)).or_default();
                e.0 += 1;
                e.1 += ms;
                last = Some(pending);
            }
            return match last {
                Some(p) => Ok(p),
                None => self.submit_one(&[], None),
            };
        }
        let t0 = std::time::Instant::now();
        let r = self.submit_one(groups, None);
        if std::env::var_os("TL_METAL_GPU_TIME").is_some() {
            eprintln!("metal: encoded {} launches in {:.3} ms", groups.iter().map(|g| g.len()).sum::<usize>(), t0.elapsed().as_secs_f64() * 1e3);
        }
        r
    }
    fn poll(&self, pending: &Pending) -> Result<bool> {
        match pending.cmd.status() {
            MTLCommandBufferStatus::Completed => Ok(true),
            MTLCommandBufferStatus::Error => check(&pending.cmd).map(|_| true),
            _ => Ok(false),
        }
    }

    fn wait(&self, pending: &Pending) -> Result<()> {
        pending.cmd.waitUntilCompleted();
        if std::env::var_os("TL_METAL_GPU_TIME").is_some() {
            eprintln!("metal: submission took {:.3} ms on the GPU", (pending.cmd.GPUEndTime() - pending.cmd.GPUStartTime()) * 1e3);
        }
        check(&pending.cmd)
    }
}


impl Metal {
    /// One command buffer for `groups`, or for the single launch `only`.
    fn submit_one(&self, groups: &[Vec<Launch<'_, Self>>], only: Option<&Launch<'_, Self>>) -> Result<Pending> {
                let cmd = self.dev.queue.commandBuffer().ok_or_else(|| Error::Execution("no command buffer".into()))?;
        let enc = cmd
            .computeCommandEncoderWithDispatchType(MTLDispatchType::Concurrent)
            .ok_or_else(|| Error::Execution("no compute encoder".into()))?;
        let mut words: Vec<u32> = Vec::new();
        let one: Vec<Vec<&Launch<'_, Self>>> = only.map(|l| vec![vec![l]]).unwrap_or_default();
        let all: Vec<Vec<&Launch<'_, Self>>> = if only.is_some() { one } else { groups.iter().map(|g| g.iter().collect()).collect() };
        for (gi, group) in all.iter().enumerate() {
            if gi > 0 {
                enc.memoryBarrierWithScope(MTLBarrierScope::Buffers);
            }
            for l in group {
                let p = l.pipeline;
                if l.bindings.len() != p.bindings || l.push.len() != p.push_bytes {
                    return Err(Error::Invalid(format!(
                        "launch has {} bindings and {} push bytes, its kernel takes {} and {}",
                        l.bindings.len(),
                        l.push.len(),
                        p.bindings,
                        p.push_bytes
                    )));
                }
                if self.profile.launches_path.is_some() {
                    let key = (p.label.clone(), l.grid, l.push.to_vec(), l.bindings.iter().map(|b| b.len).collect::<Vec<_>>());
                    let mut launches = self.profile.launches.lock().unwrap();
                    let e = launches.entry(key).or_default();
                    e.0 += 1;
                    if e.1.is_empty() {
                        // SAFETY: shared storage, `len` bytes from the binding's offset are inside the buffer
                        e.1 = l.bindings.iter().map(|b| (b.len <= SNAPSHOT_BYTES).then(|| unsafe { std::slice::from_raw_parts(b.buffer.contents().add(b.offset as usize), b.len as usize).to_vec() })).collect();
                    }
                }
                enc.setComputePipelineState(&p.pipeline.pso);
                words.clear();
                for (i, b) in l.bindings.iter().enumerate() {
                    let aligned = b.offset - b.offset % OFFSET_ALIGN;
                    words.push((b.offset - aligned) as u32);
                    // SAFETY: the buffer outlives the submission (the engine keeps it alive).
                    unsafe { enc.setBuffer_offset_atIndex(Some(&b.buffer.raw), aligned as usize, i) };
                }
                words.extend(l.push.chunks(4).map(|c| {
                    let mut w = [0u8; 4];
                    w[..c.len()].copy_from_slice(c);
                    u32::from_ne_bytes(w)
                }));
                if !words.is_empty() {
                    // SAFETY: Metal copies the bytes.
                    unsafe { enc.setBytes_length_atIndex(NonNull::new(words.as_mut_ptr() as *mut _).unwrap(), words.len() * 4, p.bindings) };
                }
                let size = |v: [u32; 3]| MTLSize { width: v[0] as usize, height: v[1] as usize, depth: v[2] as usize };
                enc.dispatchThreadgroups_threadsPerThreadgroup(size(l.grid), size(p.threads));
            }
        }
        enc.endEncoding();
        cmd.commit();
        Ok(Pending { cmd })
    }
}
